using System.ComponentModel;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Tool Implementations ---

var notebook = new Notebook();

[Description("Search the web for information on a given query. Returns a list of relevant snippets.")]
string WebSearch([Description("The search query")] string query)
{
    Console.WriteLine($"  [Tool] Searching the web for: \"{query}\"");

    // Simulated web search results keyed by topic keywords
    var results = new Dictionary<string, string[]>(StringComparer.OrdinalIgnoreCase)
    {
        ["quantum computing"] = [
            "Quantum computing uses qubits that can exist in superposition, enabling parallel computation on an exponential scale compared to classical bits.",
            "Google's Willow chip (2024) achieved quantum error correction below threshold, a major milestone for fault-tolerant quantum computing.",
            "IBM plans to deliver a 100,000-qubit system by 2033, targeting drug discovery and materials science applications.",
            "Microsoft's topological qubits promise greater stability, reducing the overhead needed for error correction.",
            "Current quantum computers face decoherence challenges, limiting computation time to microseconds without error correction."
        ],
        ["artificial intelligence"] = [
            "Large language models like GPT-4 and Claude demonstrate emergent reasoning capabilities across diverse tasks.",
            "AI agents can now use tools, browse the web, and write code autonomously using function-calling architectures.",
            "The AI safety field focuses on alignment—ensuring AI systems act in accordance with human values and intentions.",
            "Multimodal AI models process text, images, audio, and video in unified architectures.",
            "Global AI investment exceeded $200 billion in 2025, with healthcare and scientific research as top application areas."
        ],
        ["climate change"] = [
            "Global average temperatures have risen 1.2°C above pre-industrial levels as of 2024.",
            "Renewable energy capacity surpassed fossil fuels for new installations in 2023 for the first time.",
            "The IPCC AR6 report warns that limiting warming to 1.5°C requires halving emissions by 2030.",
            "Carbon capture and storage (CCS) technologies are scaling but remain expensive at $100-300 per ton of CO2.",
            "Ocean acidification has increased 30% since the industrial revolution, threatening marine ecosystems."
        ]
    };

    var matchingResults = results
        .Where(kvp => query.Contains(kvp.Key, StringComparison.OrdinalIgnoreCase)
                      || kvp.Key.Contains(query, StringComparison.OrdinalIgnoreCase))
        .SelectMany(kvp => kvp.Value)
        .ToArray();

    if (matchingResults.Length == 0)
    {
        return $"Search results for '{query}': No specific results found. The topic may require more targeted queries.";
    }

    return $"Search results for '{query}':\n" + string.Join("\n", matchingResults.Select((r, i) => $"  {i + 1}. {r}"));
}

[Description("Save a note to the research notebook for later reference when writing the summary.")]
string TakeNote(
    [Description("A short label for the note")] string title,
    [Description("The content of the note")] string content)
{
    Console.WriteLine($"  [Tool] Taking note: \"{title}\"");
    notebook.AddNote(title, content);
    return $"Note saved: \"{title}\" ({content.Length} chars)";
}

[Description("Retrieve all notes currently saved in the research notebook.")]
string GetNotes()
{
    Console.WriteLine("  [Tool] Retrieving all notes");
    var notes = notebook.GetAllNotes();
    if (notes.Count == 0)
        return "Notebook is empty. No notes have been taken yet.";
    return "Current notes:\n" + string.Join("\n\n", notes.Select(n => $"## {n.Title}\n{n.Content}"));
}

// --- Agent Setup ---

var topic = args.Length > 0 ? string.Join(' ', args) : "quantum computing";
Console.WriteLine($"Research Agent Starting...");
Console.WriteLine($"Topic: {topic}");
Console.WriteLine(new string('-', 50));

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? "sk-placeholder";
var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

IChatClient client = new OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

var chatOptions = new ChatOptions
{
    Tools =
    [
        AIFunctionFactory.Create(WebSearch),
        AIFunctionFactory.Create(TakeNote),
        AIFunctionFactory.Create(GetNotes),
    ]
};

var messages = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a research agent. Your job is to research the given topic thoroughly using the available tools.

        Follow this process:
        1. Search the web for information about the topic (try multiple queries to cover different aspects).
        2. Take notes on the key findings from your searches.
        3. Review your notes, then provide a comprehensive summary of your research.

        Always use the tools to gather information before summarizing. Take at least 3 notes before writing your final summary.
        """),
    new(ChatRole.User, $"Please research the following topic and provide a comprehensive summary: {topic}")
};

Console.WriteLine("\nAgent is researching...\n");

var response = await client.GetResponseAsync(messages, chatOptions);

Console.WriteLine(new string('-', 50));
Console.WriteLine("RESEARCH SUMMARY");
Console.WriteLine(new string('-', 50));
Console.WriteLine(response.Text);
Console.WriteLine(new string('-', 50));
Console.WriteLine($"\nNotes taken: {notebook.GetAllNotes().Count}");

// --- Notebook Class ---

class Notebook
{
    private readonly List<Note> _notes = [];

    public void AddNote(string title, string content)
    {
        _notes.Add(new Note(title, content));
    }

    public IReadOnlyList<Note> GetAllNotes() => _notes.AsReadOnly();
}

